import {SIZE,levels,key,unkey,inside,projection,check,predictionOptions} from './logic.mjs';
import {Scene} from './scene.mjs';
const $=id=>document.getElementById(id),$$=s=>[...document.querySelectorAll(s)];
let level=0,mode='explore',tool='add',builds=levels.map(()=>[]),history=levels.map(()=>[]),completed=new Set(),checked=false,overlay=false,predicted=false,solvedNow=false,predictView='front',choiceOptions=[];
const titleCase=s=>s[0].toUpperCase()+s.slice(1);
const scene=new Scene($('scene'),{onEdit:edit,onViewChange:view=>$$('[data-view]').forEach(b=>{const active=b.dataset.view===view;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})});
function say(title,detail,success=false){$('feedback-title').textContent=title;$('feedback').textContent=detail;$('message-icon').textContent=success?'✓':'◇';document.querySelector('.action-bar').classList.toggle('success',success)}
function svgDrawing(p,{overlayDrawing=null,hidden=false}={}){const pad=18,cell=31,w=pad*2+cell*SIZE;let s=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${w}" aria-hidden="true">`;
for(let i=0;i<=SIZE;i++){const a=pad+i*cell;s+=`<path d="M${pad} ${a}H${w-pad}M${a} ${pad}V${w-pad}" stroke="#d4e0e3" stroke-width=".7"/>`}
if(hidden)return s+`<rect x="${pad}" y="${pad}" width="${cell*SIZE}" height="${cell*SIZE}" fill="#edf5f3" fill-opacity=".95"/><text x="${w/2}" y="${w/2+12}" text-anchor="middle" font-family="system-ui" font-size="40" fill="#4c7c74">?</text></svg>`;
for(const k of p.filled){const [x,y]=k.split(',').map(Number);s+=`<rect x="${pad+x*cell}" y="${pad+y*cell}" width="${cell+.05}" height="${cell+.05}" fill="#bbdfd5"/>`}
for(const [x1,y1,x2,y2] of p.edges)s+=`<path d="M${pad+x1*cell} ${pad+y1*cell}L${pad+x2*cell} ${pad+y2*cell}" fill="none" stroke="#225f58" stroke-width="2.1" stroke-linecap="square"/>`;
if(overlayDrawing)for(const [x1,y1,x2,y2] of overlayDrawing.edges)s+=`<path d="M${pad+x1*cell} ${pad+y1*cell}L${pad+x2*cell} ${pad+y2*cell}" fill="none" stroke="#bc6710" stroke-width="3" stroke-dasharray="4 3"/>`;
return s+'</svg>'}
function renderViews(){const result=checked?check(builds[level],levels[level].cubes):null;for(const view of ['top','front','right']){const target=projection(levels[level].cubes,view),hidden=mode==='predict'&&view===predictView;const svg=$(`view-${view}`);const markup=svgDrawing(target,{hidden,overlayDrawing:mode==='build'&&overlay?projection(builds[level],view):null});const parsed=new DOMParser().parseFromString(markup,'image/svg+xml').documentElement;svg.setAttribute('viewBox',parsed.getAttribute('viewBox'));svg.innerHTML=parsed.innerHTML;svg.setAttribute('aria-label',hidden?`${titleCase(view)} view hidden for prediction`:`${titleCase(view)} target drawing on a ${SIZE} by ${SIZE} grid`);const status=$(`status-${view}`);status.textContent=hidden?'Predict this':result?(result.views[view]?'✓ Matches':'Check this'):'';status.className='view-status'+(result?(result.views[view]?' match':' miss'):'')}
$('your-legend').hidden=!(overlay&&mode==='build');$('overlay').setAttribute('aria-pressed',String(overlay))}
function renderNav(){$('levels').innerHTML='';levels.forEach((l,i)=>{const b=document.createElement('button');b.textContent=i===0?'Learn':String(i);b.title=l.title;b.setAttribute('aria-label',`${i===0?'Guided example':`Puzzle ${i}`}: ${l.title}${completed.has(i)?', completed':''}`);b.setAttribute('aria-current',i===level?'step':'false');b.className=(i===level?'active ':'')+(completed.has(i)?'solved':'');b.onclick=()=>startLevel(i);$('levels').append(b)})}
function setPrimary(text){$('primary-action').textContent=text+' →'}
function render(){document.body.className=`mode-${mode}`;renderNav();$('chapter').textContent=levels[level].tag;$('challenge-title').textContent=levels[level].title;$('mission').textContent=levels[level].prompt;$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode))});$$('[data-tool]').forEach(b=>{b.classList.toggle('active',b.dataset.tool===tool);b.setAttribute('aria-pressed',String(b.dataset.tool===tool))});const cubes=mode==='build'?builds[level]:levels[level].cubes;scene.set(cubes,mode==='build'?tool:'rotate');$('cube-count').textContent=`${cubes.length} ${cubes.length===1?'cube':'cubes'}`;$('model-heading').textContent=mode==='build'?'Your model':'The model';$('scene-tag').textContent=mode==='build'?(tool==='rotate'?'DRAG TO ROTATE':tool==='add'?'CLICK A FACE TO ADD':'CLICK A CUBE TO REMOVE'):'DRAG TO ROTATE';$('interaction-note').textContent=mode==='build'?'Click to edit · Drag to turn · Arrow keys to turn':'Drag to turn · Scroll to zoom · Arrow keys to turn';$('undo').disabled=history[level].length===0;$('reset').disabled=builds[level].length===0;$('prediction-panel').hidden=mode!=='predict';$('board-key').innerHTML=mode==='build'?'Match the outside outline<br>and the visible inside edges.':'The drawings stay fixed<br>as you rotate the model.';renderViews();if(mode==='explore')setPrimary('Try a prediction');else if(mode==='predict')setPrimary(predicted?'Build this model':'Choose a drawing');else setPrimary(solvedNow?(level===levels.length-1?'Explore the final model':'Next puzzle'):'Check my model');$('primary-action').disabled=mode==='predict'&&!predicted}
function setMode(next){if(!['explore','predict','build'].includes(next))throw Error('Choose Explore, Predict, or Build.');mode=next;checked=false;solvedNow=false;predicted=false;if(mode==='explore')say('Start with a different viewpoint.','Choose Front, Top, and Right. Which view hides the most cubes?');if(mode==='predict'){predictView=['front','right','top'][level%3];makePrediction();say('Look before you choose.',`Which drawing matches the ${predictView} view? You can rotate the model to help.`)}if(mode==='build')say('Build the object shown in the drawings.','Click the base to place your first cube. Then click cube faces to add more.');render()}
function startLevel(i){if(!Number.isInteger(i)||i<0||i>=levels.length)throw Error('Choose a challenge from 0 through 5.');level=i;scene.setView('iso');setMode(i===0?'explore':'build')}
function snapshot(){history[level].push(structuredClone(builds[level]));if(history[level].length>100)history[level].shift()}
function edit(cell,action){if(mode!=='build')return{ok:false,message:'Switch to Build to edit cubes.'};if(!inside(cell)){say('Stay inside the building space.','Use columns, heights, and depths from 1 to 4.');return{ok:false,message:'Out of bounds'}}const s=new Set(builds[level].map(key)),k=key(cell);if(action==='add'&&s.has(k)){say('There is already a cube here.','Choose an empty space or click another face.');return{ok:false,message:'Occupied'}}if(action==='remove'&&!s.has(k)){say('This space is already empty.','Choose a cube to remove.');return{ok:false,message:'Empty'}}snapshot();if(action==='add')s.add(k);else if(action==='remove')s.delete(k);else throw Error('Unknown edit action');builds[level]=[...s].map(unkey);checked=false;solvedNow=false;render();say('Keep checking all three views.','Use “Show my outline” to compare your model with the target.');return{ok:true,cubes:builds[level].length}}
function verify(){checked=true;const result=check(builds[level],levels[level].cubes);solvedNow=result.solved;if(result.solved){completed.add(level);say('All three views match. You solved it!',level===5?'Build this one with snap cubes, then sketch and explain the three views.':'Before moving on: which view helped you most, and why?',true)}else if(!result.rules.ok)say('Check your construction.',result.rules.reason);else{const yes=Object.keys(result.views).filter(v=>result.views[v]),no=Object.keys(result.views).filter(v=>!result.views[v]);say(yes.length?`${yes.map(titleCase).join(' and ')} ${yes.length===1?'view matches':'views match'}.`:'Let’s compare the drawings.',`Check ${no.map(titleCase).join(' and ')}. ${levels[level].hint}`)}render();return result}
function makePrediction(){choiceOptions=predictionOptions(levels[level].cubes,predictView,level);$('predict-view-name').textContent=predictView;$('prediction-choices').innerHTML='';choiceOptions.forEach((option,i)=>{const b=document.createElement('button');b.setAttribute('aria-label',`Choose drawing ${String.fromCharCode(65+i)}`);b.innerHTML=svgDrawing(option.drawing)+`<span>${String.fromCharCode(65+i)}</span>`;b.onclick=()=>{if(option.correct){predicted=true;b.classList.add('correct');say('Yes—that is the view!',`Now use all three drawings to build the object yourself.`,true);setPrimary('Build this model');$('primary-action').disabled=false}else{b.classList.add('incorrect');say('Take another look.',`Choose the ${titleCase(predictView)} camera button, then compare the outline and visible inside edges.`)}};$('prediction-choices').append(b)})}
$$('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$$('[data-tool]').forEach(b=>b.onclick=()=>{tool=b.dataset.tool;render()});$$('[data-view]').forEach(b=>b.onclick=()=>scene.setView(b.dataset.view));$('zoom-in').onclick=()=>scene.zoomBy(1.1);$('zoom-out').onclick=()=>scene.zoomBy(1/1.1);$('overlay').onclick=()=>{overlay=!overlay;renderViews()};$('undo').onclick=()=>{if(!history[level].length)return;builds[level]=history[level].pop();checked=false;solvedNow=false;render();say('Last edit undone.','Keep building, or check the three views again.')};$('reset').onclick=()=>{if(!builds[level].length)return;snapshot();builds[level]=[];checked=false;solvedNow=false;render();say('A fresh start.','Your previous model is still one Undo away.')};for(const axis of ['x','y','z'])for(let i=1;i<=SIZE;i++){const o=document.createElement('option');o.value=i-1;o.textContent=i;$(`coord-${axis}`).append(o)}const chosenCell=()=>['x','y','z'].map(a=>Number($(`coord-${a}`).value));$('place-cube').onclick=()=>edit(chosenCell(),'add');$('remove-cube').onclick=()=>edit(chosenCell(),'remove');$('primary-action').onclick=()=>{if(mode==='explore')setMode('predict');else if(mode==='predict'&&predicted)setMode('build');else if(mode==='build'){if(solvedNow){if(level===5)setMode('explore');else startLevel(level+1)}else verify()}};$('help-open').onclick=()=>$('help').showModal();$('help-close').onclick=()=>$('help').close();$('help').addEventListener('click',e=>{if(e.target===$('help')){const r=$('help').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('help').close()}});
// Keep the prediction activity beside the model so students can see both at once.
document.querySelector('.model-panel').insertBefore($('prediction-panel'),document.querySelector('.model-tools'));
startLevel(0);
// The page and optional agent tools share the same actions and state.
const state=()=>({challenge:level,title:levels[level].title,mode,cubes:structuredClone(mode==='build'?builds[level]:levels[level].cubes),completed:[...completed],checked,solved:solvedNow});
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'read_multiview_workshop',description:'Read the current puzzle, mode, and displayed cubes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>state()});register({name:'start_multiview_challenge',description:'Select a challenge (0 is the guided example; 1–5 are puzzles) and workshop mode.',inputSchema:{type:'object',properties:{challenge:{type:'integer',minimum:0,maximum:5},mode:{type:'string',enum:['explore','predict','build']}},required:['challenge','mode'],additionalProperties:false},execute:input=>{if(!input||!Number.isInteger(input.challenge)||input.challenge<0||input.challenge>5||!['explore','predict','build'].includes(input.mode))throw Error('Invalid challenge or mode');startLevel(input.challenge);setMode(input.mode);return state()}});register({name:'edit_multiview_cubes',description:'Add or remove cube cells in Build mode. Coordinates are zero-based, 0–3. Applies edits to the visible model.',inputSchema:{type:'object',properties:{action:{type:'string',enum:['add','remove']},cells:{type:'array',minItems:1,maxItems:64,items:{type:'array',minItems:3,maxItems:3,items:{type:'integer',minimum:0,maximum:3}}}},required:['action','cells'],additionalProperties:false},execute:input=>{if(!input||!['add','remove'].includes(input.action)||!Array.isArray(input.cells)||!input.cells.length||input.cells.length>64||input.cells.some(c=>!inside(c)))throw Error('Invalid cube edit');if(mode!=='build')throw Error('Switch to Build first');const results=input.cells.map(c=>edit(c,input.action));return{results,state:state()}}});register({name:'check_multiview_model',description:'Check the current construction against all three target drawings and the build rules.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{if(mode!=='build')throw Error('Switch to Build first');return verify()}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
